def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    opp_defects = 0
    for a in opp:
        if a == 'D':
            opp_defects += 1

    # Opening: short cooperative phase to establish mutual cooperation.
    if n < 4:
        return 'C'

    # Endgame: once mutual cooperation has been established, defect at the very end
    # to capture the sucker payoff from conditional cooperators.
    remaining = 100 - n
    if remaining <= 2:
        if opp_defects == 0:
            return 'D'
        last_opp = opp[-1]
        if last_opp == 'C':
            return 'D'
        return 'D'

    # Severe exploitation: opponent defects most of the time.
    if opp_defects * 5 >= n * 3:
        if n % 13 == 0:
            return 'C'
        return 'D'

    last_opp = opp[-1]
    last_me = me[-1]

    # Opponent just defected. Retaliate, but forgive cooperative opponents
    # quickly to avoid long mutual-defection traps.
    if last_opp == 'D':
        coop = n - opp_defects
        if coop * 2 >= n and rng.random() < 0.30:
            return 'C'
        # Forgive an isolated defection after we cooperated, to reset cooperation.
        if n >= 2 and opp[-2] == 'C' and last_me == 'C':
            if rng.random() < 0.35:
                return 'C'
        # Break potential echo of mutual defection.
        if n >= 2 and last_me == 'D' and opp[-2] == 'D':
            if rng.random() < 0.25:
                return 'C'
        return 'D'

    # Opponent just cooperated. Cooperate, but probe very cooperative
    # opponents occasionally in the midgame.
    if opp_defects == 0:
        if n >= 8 and remaining > 15 and n % 9 == 0:
            return 'D'
        return 'C'

    # Opponent has defected at least once but not frequently: mostly cooperate.
    if opp_defects * 4 <= n:
        if n % 17 == 0 and remaining > 20:
            return 'D'
        return 'C'

    # Moderate defection rate: retaliate for last defection, otherwise cooperate.
    if rng.random() < 0.12:
        return 'D'
    return 'C'
